import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Copy, ExternalLink, Facebook, Instagram, Twitter, Share2, Check } from 'lucide-react';
import toast from 'react-hot-toast';
import productService from '../../services/productService';

const platforms = [
    { key: 'facebook', name: 'Facebook', icon: Facebook, color: 'bg-blue-600', hoverColor: 'hover:bg-blue-700' },
    { key: 'instagram', name: 'Instagram', icon: Instagram, color: 'bg-pink-600', hoverColor: 'hover:bg-pink-700' },
    { key: 'twitter', name: 'X (Twitter)', icon: Twitter, color: 'bg-sky-600', hoverColor: 'hover:bg-sky-700' },
];

const AdSetup = () => {
    const [selectedPlatform, setSelectedPlatform] = useState('facebook');
    const [copiedId, setCopiedId] = useState(null);

    const { data, isLoading } = useQuery({
        queryKey: ['products-ads', selectedPlatform],
        queryFn: () => productService.getProductsForAds(selectedPlatform)
    });

    const copyToClipboard = (text, id) => {
        navigator.clipboard.writeText(text);
        setCopiedId(id);
        toast.success('Link copied to clipboard!');
        setTimeout(() => setCopiedId(null), 2000);
    };

    const generateAdHtml = (product, platform) => {
        const url = product.adUrl[platform];
        return `<a href="${url}" target="_blank">Order ${product.name} Now - $${product.price}</a>`;
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                    Ad Campaign Setup
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Generate product links for social media advertising
                </p>
            </div>

            {/* Instructions Card */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-xl p-6 text-white"
            >
                <div className="flex items-start gap-4">
                    <Share2 className="h-8 w-8 flex-shrink-0" />
                    <div>
                        <h3 className="text-lg font-semibold mb-2">How It Works</h3>
                        <ol className="space-y-2 text-sm text-indigo-100">
                            <li>1. Select a product and platform below</li>
                            <li>2. Copy the generated tracking link</li>
                            <li>3. Use the link in your social media ads (Facebook Ads Manager, Instagram Promotions, Twitter Ads)</li>
                            <li>4. When customers click and order, the UTM parameters track which ad brought them</li>
                            <li>5. Orders automatically appear in the system for sales reps to process</li>
                        </ol>
                    </div>
                </div>
            </motion.div>

            {/* Platform Selector */}
            <div className="flex gap-2 flex-wrap">
                {platforms.map((platform) => (
                    <button
                        key={platform.key}
                        onClick={() => setSelectedPlatform(platform.key)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${selectedPlatform === platform.key
                                ? `${platform.color} text-white shadow-lg scale-105`
                                : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                            }`}
                    >
                        <platform.icon className="h-5 w-5" />
                        {platform.name}
                    </button>
                ))}
            </div>

            {/* Products List */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                        Your Products - Ad Links
                    </h3>
                </div>

                <div className="divide-y divide-gray-200 dark:divide-gray-700">
                    {isLoading ? (
                        <div className="p-8 text-center">
                            <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto" />
                        </div>
                    ) : data?.products?.length === 0 ? (
                        <div className="p-8 text-center text-gray-500">
                            No products available for ads
                        </div>
                    ) : (
                        data?.products?.map((product) => (
                            <div key={product.id} className="p-4 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors">
                                <div className="flex items-center gap-4">
                                    <div className="h-16 w-16 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden flex-shrink-0">
                                        {product.imageUrl ? (
                                            <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" />
                                        ) : (
                                            <Package className="h-8 w-8 text-gray-400" />
                                        )}
                                    </div>

                                    <div className="flex-1 min-w-0">
                                        <h4 className="font-medium text-gray-900 dark:text-white truncate">
                                            {product.name}
                                        </h4>
                                        <p className="text-sm text-gray-500 dark:text-gray-400">
                                            ${product.price}
                                        </p>

                                        <div className="mt-2 flex items-center gap-2">
                                            <input
                                                type="text"
                                                value={product.adUrl[selectedPlatform]}
                                                readOnly
                                                className="flex-1 text-xs bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-600 rounded px-3 py-1.5 text-gray-600 dark:text-gray-400 truncate"
                                            />

                                            <button
                                                onClick={() => copyToClipboard(product.adUrl[selectedPlatform], product.id)}
                                                className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                                            >
                                                {copiedId === product.id ? (
                                                    <Check className="h-4 w-4 text-emerald-500" />
                                                ) : (
                                                    <Copy className="h-4 w-4 text-gray-400" />
                                                )}
                                            </button>

                                            <a
                                                href={product.adUrl[selectedPlatform]}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                                            >
                                                <ExternalLink className="h-4 w-4 text-gray-400" />
                                            </a>
                                        </div>

                                        {/* UTM Parameters */}
                                        <div className="mt-2 flex flex-wrap gap-1">
                                            {Object.entries(product.utmParams).map(([key, value]) => (
                                                <span key={key} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-mono bg-gray-100 dark:bg-gray-900 text-gray-600 dark:text-gray-400">
                                                    {key}={value}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Ad Code Generator */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Quick Tips
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <TipCard
                        platform="Facebook"
                        tip="Create a Facebook Ad with the 'Traffic' objective. Use the product link as the destination URL. Add eye-catching product images."
                    />
                    <TipCard
                        platform="Instagram"
                        tip="Use Instagram Shopping if available, or create Story ads with swipe-up links. The product link works in bio too."
                    />
                    <TipCard
                        platform="Twitter"
                        tip="Create Promoted Tweets with compelling product descriptions. Use high-quality images and clear CTAs."
                    />
                </div>
            </div>
        </div>
    );
};

const TipCard = ({ platform, tip }) => (
    <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
        <h4 className="font-medium text-gray-900 dark:text-white mb-2">{platform}</h4>
        <p className="text-sm text-gray-600 dark:text-gray-400">{tip}</p>
    </div>
);

export default AdSetup;
